import {
  getLocalSolvedPuzzleMap,
  PuzzleInfoBox,
  ClickableMonarchDevice,
} from "@hunt/puzzle-components";

const CAPSTONE_SLUG = "three_dog_night";

const PuzzleComponent = () => {
  const solvedPuzzles = getLocalSolvedPuzzleMap();

  return CAPSTONE_SLUG in solvedPuzzles ? (
    <div className="flex items-center gap-2">
      The Old Bark Town Puzzmon want to play fetch with you, can you help all of
      them reach their favorite toys?
      <ClickableMonarchDevice zoneSlug="old_bark_town" className="w-20" />,
    </div>
  ) : (
    <PuzzleInfoBox copyable={false}>
      You need to solve the{" "}
      <a href={`/puzzles/${CAPSTONE_SLUG}`}>Old Bark Town capstone puzzle</a>{" "}
      before you can access this task.
    </PuzzleInfoBox>
  );
};

export default PuzzleComponent;
